import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import '../styles/global.css';
const Contact = () => {
    //enviroments:
    //REACT_APP_API_NEWS_STATSUP=https://utils.statsup.cl/api/get-json/cfGx9nhpdTzK
    //REACT_APP_API_EMAILJS_SERVICE_ID=service_qydy9gm
    //REACT_APP_API_EMAILJS_TEMPLATE_ID=template_p8u2ifk
    //REACT_APP_API_EMAILJS_USER_ID=xxpDd812svy3oKSU
    //REACT_APP_API_EMAILJS_ACCESS_TOKEN=6eNIJ7hixLP51cRrudwGc
    //{
    //    "service_id" : "",
    //    "template_id" : "",
    //    "user_id" : "-",
    //    "accessToken" : "",
    //    "template_params" : {
    //        "name": "Fernando",
    //        "time": "Fecha y Hora actual",
    //        "message": "Mensaje de prueba",
    //        "email": "correo@dom.cl"
    //    }
    //}
    const handleSubmit = (e) => {
        e.preventDefault();

        // Obtener valores del formulario
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        const message = document.getElementById('message').value.trim();

        if (!name || !email || !message) {
            alert('Por favor, complete todos los campos.');
            return;
        }

        // Validación de correo simple
        const atIndex = email.indexOf('@');
        const dotIndex = email.lastIndexOf('.');
        if (atIndex < 1 || dotIndex < atIndex + 2 || dotIndex === email.length - 1) {
            alert('Por favor, ingrese un correo válido.');
            return;
        }

        // Preparar payload usando variables de entorno comentadas
        const payload = {
            service_id: process.env.REACT_APP_API_EMAILJS_SERVICE_ID,
            template_id: process.env.REACT_APP_API_EMAILJS_TEMPLATE_ID,
            user_id: process.env.REACT_APP_API_EMAILJS_USER_ID,
            accessToken: process.env.REACT_APP_API_EMAILJS_ACCESS_TOKEN,
            template_params: {
                name,
                time: new Date().toLocaleString(),
                message,
                email
            }
        };

        // Endpoint EmailJS (por defecto)
        const endpoint = process.env.REACT_APP_API_EMAILJS_ENDPOINT || 'https://api.emailjs.com/api/v1.0/email/send';

        setSending(true);

        fetch(endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(payload)
        })
            .then((res) => {
                if (!res.ok) throw new Error(`HTTP ${res.status}`);
                return res.json();
            })
            .then(() => {
                alert('Mensaje enviado. Gracias por contactarnos.');
                e.target.reset();
            })
            .catch((err) => {
                console.error('Error enviando mensaje:', err);
                console.log(JSON.stringify(payload));
            })
            .finally(() => setSending(false));
    };

    const [sending, setSending] = useState(false);

    return (
        <>
            <Navbar />
            <div className="container mt-5">
                <div className="row">
                    <div className="col-md-6">
                        <h2 className="mb-4">Contáctanos</h2>
                        <form className="d-grid" onSubmit={handleSubmit}>
                            <div className="mb-3">
                                <label htmlFor="name" className="form-label">Nombre</label>
                                <input type="text" className="form-control" id="name" required />
                            </div>
                            <div className="mb-3">
                                <label htmlFor="email" className="form-label">Email</label>
                                <input type="email" className="form-control" id="email" required />
                            </div>
                            <div className="mb-3">
                                <label htmlFor="message" className="form-label">Mensaje</label>
                                <textarea className="form-control" id="message" rows="5" required></textarea>
                            </div>
                            <button type="submit" className="mt-2 btn btn-primary">Enviar Mensaje</button>
                        </form>
                    </div>
                    <div className="col-md-6">
                        <h2 className="mb-4">Información de Contacto</h2>
                        <div className="card">
                            <div className="card-body">
                                <h5 className="card-title">Oficina Central</h5>
                                <p><i className="fas fa-map-marker-alt me-2"></i> Santiago, Chile</p>
                                <p><i className="fas fa-phone me-2"></i> +56 2 2345 6789</p>
                                <p><i className="fas fa-envelope me-2"></i> info@tea.com</p>
                                <p><i className="fas fa-clock me-2"></i> Lunes a Viernes: 9:00 - 18:00</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Footer />
        </>
    );
};

export default Contact;
